etlJobs.sparqlTemplate:
PREFIX : <https://example.org/rail/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

CONSTRUCT {
  ?station a :Station ;
    :name ?name ;
    :zone ?zone ;
    :stepFree ?stepFree ;
    :opened ?opened ;
    geo:hasGeometry [ geo:asWKT ?wkt ] .
}
WHERE {
  VALUES (?slug ?name ?zone ?stepFree ?opened ?wkt) {
    (UNDEF UNDEF UNDEF UNDEF UNDEF UNDEF)
  }
  BIND(IRI(CONCAT("https://example.org/rail/", ENCODE_FOR_URI(?slug))) AS ?station)
}

PREFIX : <https://example.org/rail/>

CONSTRUCT {
  ?departure a :Departure ;
    :from ?station ;
    :fromName ?stationName ;
    :line ?line ;
    :towards ?towards ;
    :dayType ?dayType ;
    :time ?time .
}
WHERE {
  VALUES (?departureId ?stationId ?stationName ?lineId ?towardsId ?dayTypeId ?time) {
    (UNDEF UNDEF UNDEF UNDEF UNDEF UNDEF UNDEF)
  }
  BIND(IRI(CONCAT("https://example.org/rail/departure/", ENCODE_FOR_URI(?departureId))) AS ?departure)
  BIND(IRI(CONCAT("https://example.org/rail/", ENCODE_FOR_URI(?stationId))) AS ?station)
  BIND(IRI(CONCAT("https://example.org/rail/", ENCODE_FOR_URI(?lineId))) AS ?line)
  BIND(IRI(CONCAT("https://example.org/rail/", ENCODE_FOR_URI(?towardsId))) AS ?towards)
  BIND(IRI(CONCAT("https://example.org/rail/", ENCODE_FOR_URI(?dayTypeId))) AS ?dayType)
}
